{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "There are concerns about effects on mental health, 2-4 particularly among groups vulnerable to health or social and economic effects of COVID-19, including older individuals; children and adolescents; people with pre-existing medical or mental health conditions; essential services personnel; and individuals marginalized due to poverty, race/ethnicity, or other factors.",
      "reason": "The introduction describes concerns about mental health effects but does not explicitly describe the current state of knowledge and important uncertainties in a way that is directly attributable to evidence gaps/uncertainties."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Scalable mental health interventions, which are interventions that can be feasibly delivered to large numbers of people affected by adversity, are needed.",
      "reason": "The text explains the need for scalable interventions in the context of ongoing/likely persistent mental health implications."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "We identified 5 systematic reviews 11-15 that have attempted to synthesize evidence on mental health interventions for nonhospitalised children, adolescents, or adults in COVID-19, but none included any randomised controlled trials (RCTs) from COVID-19 for people not quarantined or undergoing treatment due to COVID-19.",
      "reason": "The manuscript cites prior systematic reviews and explains the specific gap (no COVID-19 RCTs for the target population in those reviews), motivating the current review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence in the retrieved material describes a proposed mechanism of action for the interventions."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence in the retrieved material provides a logic model or hypothesised relationships between intervention components and outcomes."
    }
  ],
  "confidence": 62
